PortHandler.check_usb_devices = function(callback) {
  if (typeof chrome === 'undefined' || !chrome.usb) {
    if (callback) {
      callback(false);
    }
    return;
  }
  chrome.usb.getDevices(usbDevices, function(result) {
    if (result.length) {
      if (!$('div#port-picker #port [value=\'DFU\']').length) {
        $('div#port-picker #port').append($('<option/>', {
          value: 'DFU',
          text: 'DFU',
          data: {
            isDFU: true
          }
        }));
        $('div#port-picker #port').val('DFU');
      }
      self.dfu_available = true;
    } else {
      if ($('div#port-picker #port [value=\'DFU\']').length) {
        $('div#port-picker #port [value=\'DFU\']').remove();
      }
      self.dfu_available = false;
    }
    if (callback) {
      callback(self.dfu_available);
    }
  });
};

PortHandler.update_port_select = function(ports) {
  var i;
  $('div#port-picker #port').html('');
  i = 0;
  while (i < ports.length) {
    $('div#port-picker #port').append($('<option/>', {
      value: ports[i],
      text: ports[i],
      data: {
        isManual: false
      }
    }));
    i++;
  }
  $('div#port-picker #port').append($('<option/>', {
    value: 'manual',
    i18n: 'portsSelectManual',
    data: {
      isManual: true
    }
  }));
  i18n.localizePage();
};

